/**
 * Tra cứu nghĩa tiếng Việt cho một câu, cụm từ hoặc tiêu đề
 */
export function getVietnameseMeaning(text: string): string | undefined {
  if (!text) return undefined;
  const trimmed = text.trim();
  if (VIETNAMESE_TRANSLATIONS[trimmed]) {
    return VIETNAMESE_TRANSLATIONS[trimmed];
  }

  // Thử tra cứu không phân biệt dấu hai chấm cuối câu
  const withoutColon = trimmed.replace(/:$/, '').trim();
  if (VIETNAMESE_TRANSLATIONS[withoutColon]) {
    return VIETNAMESE_TRANSLATIONS[withoutColon];
  }

  // Tra cứu theo từ điển con
  for (const [key, val] of Object.entries(VIETNAMESE_TRANSLATIONS)) {
    if (trimmed.toLowerCase() === key.toLowerCase()) {
      return val;
    }
  }

  return undefined;
}
